// Sound effects + background music. Files live in android/app/src/main/res/raw
// (generated by tools/make_sounds.py — all original, no copyrighted tunes).
import {AppState} from 'react-native';
import Sound from 'react-native-sound';

export type Sfx =
  | 'tap'
  | 'pop'
  | 'correct'
  | 'wrong'
  | 'win'
  | 'star'
  | 'flip'
  | 'magic'
  | 'swoosh'
  | 'note0'
  | 'note1'
  | 'note2'
  | 'note3'
  | 'note4'
  | 'note5';
export type Track = 'menu' | 'game';

const FILES: Record<Sfx, string> = {
  tap: 'sfx_tap.ogg',
  pop: 'sfx_pop.ogg',
  correct: 'sfx_correct.ogg',
  wrong: 'sfx_wrong.ogg',
  win: 'sfx_win.ogg',
  star: 'sfx_star.ogg',
  flip: 'sfx_flip.ogg',
  magic: 'sfx_magic.ogg',
  swoosh: 'sfx_swoosh.ogg',
  note0: 'note_0.ogg',
  note1: 'note_1.ogg',
  note2: 'note_2.ogg',
  note3: 'note_3.ogg',
  note4: 'note_4.ogg',
  note5: 'note_5.ogg',
};
const TRACKS: Record<Track, string> = {menu: 'music_menu.ogg', game: 'music_game.ogg'};
const MUSIC_VOLUME: Record<Track, number> = {menu: 0.4, game: 0.28};
const VOICES = 3; // copies per effect so fast taps can overlap

let sfxOn = true;
let musicOn = true;
let appActive = AppState.currentState === 'active';
let started = false;
const pool: Partial<Record<Sfx, Sound[]>> = {};
const cursor: Partial<Record<Sfx, number>> = {};
const music: Partial<Record<Track, Sound>> = {};
const musicReady: Partial<Record<Track, boolean>> = {};
let wanted: Track | null = null;
let playing: Track | null = null;

function load(file: string, onReady?: (s: Sound) => void): Sound {
  // basePath must be passed explicitly: with (file, callback) the library
  // treats the callback as basePath and the raw resource never resolves.
  const s: Sound = new Sound(file, Sound.MAIN_BUNDLE, (err: unknown) => {
    if (!err && onReady) {
      onReady(s);
    }
  });
  return s;
}

export function initSounds() {
  if (started) {
    return;
  }
  started = true;
  try {
    Sound.setCategory('Ambient', true); // mix with other audio, never steal focus
  } catch {
    // ignore on platforms without categories
  }
  (Object.keys(FILES) as Sfx[]).forEach(name => {
    pool[name] = Array.from({length: VOICES}, () => load(FILES[name]));
    cursor[name] = 0;
  });
  AppState.addEventListener('change', st => {
    appActive = st === 'active';
    refreshMusic();
  });
}

/** Play a sound effect (no-op when sounds are off). */
export function sfx(name: Sfx, volume = 1) {
  if (!sfxOn || !appActive) {
    return;
  }
  const voices = pool[name];
  if (!voices) {
    return;
  }
  const i = ((cursor[name] ?? 0) + 1) % voices.length;
  cursor[name] = i;
  const s = voices[i];
  try {
    s.stop(() => {
      s.setVolume(volume);
      s.play();
    });
  } catch {
    // ignore
  }
}

/** Musical note 0..5 (C D E G A C) — used by Simon pads and spelling. */
export function note(i: number) {
  sfx(`note${((i % 6) + 6) % 6}` as Sfx, 0.9);
}

function refreshMusic() {
  const target = musicOn && appActive ? wanted : null;
  if (playing && playing !== target) {
    music[playing]?.pause();
    playing = null;
  }
  if (target && playing !== target) {
    const s = music[target];
    if (s && musicReady[target]) {
      s.setNumberOfLoops(-1);
      s.setVolume(MUSIC_VOLUME[target]);
      s.play();
      playing = target;
    } else if (!s) {
      music[target] = load(TRACKS[target], () => {
        musicReady[target] = true;
        refreshMusic();
      });
    }
  }
}

/** Ask for a background track (or null for silence). */
export function setTrack(track: Track | null) {
  wanted = track;
  refreshMusic();
}

export function setSoundPrefs(opts: {music: boolean; sfx: boolean}) {
  musicOn = opts.music;
  sfxOn = opts.sfx;
  refreshMusic();
}
